contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        // record owner before
        address beforeOwner = c.owner();

        // try to call setOwner from this contract (which is NOT the original admin of C)
        bool reverted;
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            // success should be true per function
            require(success == true);
        } catch {
            reverted = true;
        }

        // read owner after
        address afterOwner = c.owner();

        // General invariant: if the call reverted, owner must be unchanged; if it didn't revert, owner must equal the provided newOwner
        assert(reverted ? (afterOwner == beforeOwner) : (afterOwner == newOwner));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes a candidate new owner and a flag indicating
    // whether we should attempt the call as admin. We cannot change msg.sender here,
    // but the contract C was deployed with this InvMutTest as deployer, so InvMutTest is the admin.
    function run(address newOwner, bool doCall) public payable {
        require(true);

        // read owner before
        address ownerBefore = c.owner();

        bool reverted = false;
        bool ret = false;
        if (doCall) {
            // InvMutTest is the admin (it deployed C), so this call should succeed and return true
            try c.setOwner(newOwner) returns (bool ok) {
                ret = ok;
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        address ownerAfter = c.owner();

        // General rule:
        // - If we attempted the call and it did not revert, then it returned true and owner changed to newOwner.
        // - If we did not attempt the call or the call reverted, owner stays as before.
        assert(
            // case: attempted and not reverted
            (doCall && !reverted && ret == true && ownerAfter == newOwner)
            // case: not attempted or reverted -> owner unchanged
            || ((!doCall || reverted) && ownerAfter == ownerBefore)
        );
    }

    receive() external payable { }
}

